'use strict';
const $=id=>document.getElementById(id);
const state={token:window.__workspaceToken||'',busy:false,lookup:null,currentJob:null,credits:null,slideSeq:0,activeSlide:null,records:new Map()};delete window.__workspaceToken;
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let toastTimer;
function toast(text){$('toast').textContent=text;$('toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').hidden=true,4200)}
async function api(path,body){if(!state.token){location.replace('/');throw new Error('Enter your password to open the app.')}const response=await fetch(path,{method:body?'POST':'GET',headers:{Authorization:`Bearer ${state.token}`,...(body?{'Content-Type':'application/json'}:{})},body:body?JSON.stringify(body):undefined,signal:AbortSignal.timeout(65000),cache:'no-store'});let result;try{result=await response.json()}catch{throw new Error('The server returned an unreadable response.')}if(!response.ok){const err=new Error(result.error||'The request could not be completed.');err.payload=result;throw err}return result}
function validLinkedIn(value){try{const u=new URL(value);if(u.protocol!=='https:'||!['linkedin.com','www.linkedin.com'].includes(u.hostname)||!/^\/in\/[^/]+\/?$/i.test(u.pathname))throw Error();u.hostname='www.linkedin.com';u.search='';u.hash='';if(!u.pathname.endsWith('/'))u.pathname+='/';return u.href}catch{return null}}
function initials(name){return String(name||'?').split(/\s+/).filter(Boolean).slice(0,2).map(x=>x[0]).join('').toUpperCase()||'?'}
function timeLabel(iso){if(!iso)return'—';const d=new Date(iso);if(Number.isNaN(+d))return'—';return d.toLocaleTimeString([],{hour:'2-digit',minute:'2-digit',second:'2-digit'})}
function ageLabel(iso){if(!iso)return'not available';const ms=Date.now()-new Date(iso).getTime();if(!Number.isFinite(ms)||ms<0)return'just now';const s=Math.floor(ms/1000);if(s<5)return'just now';if(s<60)return`${s}s ago`;return`${Math.floor(s/60)}m ago`}
function updateCredits(summary){if(!summary){$('credits').hidden=true;return}state.credits=summary;$('credits').hidden=false;const total=summary.totalCreditsRemaining;const freshest=(summary.routes||[]).map(r=>r.observedAt).filter(Boolean).sort().at(-1);$('credits-label').textContent=total==null?'Credits unavailable':`${Number(total).toLocaleString()} credits`;$('credits').title=total==null?'A fresh Seamless balance could not be confirmed for every configured organization.':`Provider snapshot ${ageLabel(freshest)}`;renderCreditsDialog()}
function renderCreditsDialog(){
  const summary=state.credits||{},routes=Array.isArray(summary.routes)?summary.routes:[];
  const rows=routes.map(r=>{const usage=r.usageState||'STANDBY';const cls=usage==='ACTIVE'?'active':usage==='EXHAUSTED'?'exhausted':usage==='UNAVAILABLE'?'bad':'standby';return `<div class="credit-route ${cls}"><div><strong>${esc((r.id||'route').toUpperCase())}</strong><small>${esc(r.keySource||'Seamless API key')}</small></div><div><strong>${Number.isFinite(r.creditsRemaining)?Number(r.creditsRemaining).toLocaleString():'—'}</strong><small>${r.fresh?'fresh provider balance':'unavailable'}</small></div><div class="credit-time"><strong>${esc(timeLabel(r.observedAt))}</strong><small>${esc(ageLabel(r.observedAt))}</small></div><span class="route-state ${cls}">${esc(usage)}</span>${r.error?`<small class="route-error">${esc(r.error)}</small>`:''}</div>`}).join('');
  const allFresh=summary.allFresh===true;
  $('credits-content').innerHTML=`<div class="credit-number ${allFresh?'':'uncertain'}"><strong>${allFresh&&Number.isFinite(summary.totalCreditsRemaining)?Number(summary.totalCreditsRemaining).toLocaleString():'—'}</strong><span>${allFresh?'combined fresh provider balance':'combined total withheld because every route is not fresh'}</span></div><div class="route-policy"><strong>PRIMARY-first</strong><span>PRIMARY receives new enrichment while it has credits. SECONDARY becomes active only after PRIMARY is confirmed exhausted.</span></div><div class="credit-route-list">${rows||'<p class="fineprint">No Seamless routes were returned.</p>'}</div><div class="credit-facts"><div><span>Authoritative source</span><strong>X-PublicAPI-Credits</strong></div><div><span>Refresh policy</span><strong>Fresh API probe every 10s</strong></div><div><span>Active organization</span><strong>${esc((summary.activeRouteId||'—').toUpperCase())}</strong></div><div><span>Local fallback</span><strong>Never used for displayed total</strong></div></div><p class="fineprint">The number is a Seamless provider snapshot, not a local counter. If a fresh authenticated response omits the credit header or fails, Beast shows unavailable instead of reusing an older balance.</p>`;
}
function diagnosticReport(job){
  const d=job?.data||{};
  return JSON.stringify({
    reportType:'Prospecting Beast Seamless diagnostic',
    build:'40.1.0-test',
    warning:'API/auth secrets are redacted. Contact data is intentionally preserved for debugging.',
    linkedinUrl:job?.normalizedUrl||d.linkedinUrl||null,
    route:{id:job?.routeId||null,keySource:job?.keySource||null},
    guardrails:{submittedContacts:job?.submittedContacts??null,maxChargeableSubmissions:job?.maxChargeableSubmissions??null,requestIds:job?.requestIds||[],automaticRetry:false},
    credits:{before:job?.beforeCredits??null,beforeObservedAt:job?.beforeCreditsObservedAt||null,after:job?.afterCredits??null,afterObservedAt:job?.afterCreditsObservedAt||null,observedDelta:job?.creditDelta??null,anomaly:job?.creditAnomaly===true},
    finalState:{status:job?.status||null,providerStatus:job?.providerStatus||null,message:job?.message||null},
    parsedContact:d&&Object.keys(d).length?{fullName:d.fullName||null,company:d.company||null,title:d.title||null,emails:d.emails||[],phones:d.phones||[],contactMethods:d.contactMethods||[],jobHistory:d.jobHistory||[],raw:d.raw||null}:null,
    seamlessHttpTrace:Array.isArray(job?.diagnosticTrace)?job.diagnosticTrace:[]
  },null,2)
}
function diagnosticDrawer(job){const count=Array.isArray(job?.diagnosticTrace)?job.diagnosticTrace.length:0;return `<details class="data-drawer diagnostic-drawer"><summary><span>Seamless diagnostic trace</span><b>${count}</b></summary><div class="drawer-content diagnostic-content"><p>This is the provider exchange for this enrichment only. API keys and auth secrets are redacted; contact data remains visible.</p><button type="button" class="diagnostic-copy" data-copy-diagnostic="1">Copy diagnostic report</button><small>Paste the copied JSON into ChatGPT so we can inspect the exact request, headers, responses and credit snapshots.</small></div></details>`}
function copyButton(value){return value?`<button class="copy-button" data-copy="${esc(value)}">Copy</button>`:''}
function methodRows(label,methods){const arr=Array.isArray(methods)?methods:[];if(!arr.length)return'';return `<section class="method-group"><div class="method-group-head"><strong>${esc(label)}</strong><span>${arr.length}</span></div><div class="method-grid">${arr.map(m=>`<div class="method-row"><div><span class="method-type">${m.kind==='email'?'EMAIL':'PHONE'}${m.label?` · ${esc(m.label)}`:''}</span>${m.kind==='email'?`<a href="mailto:${esc(m.value)}">${esc(m.value)}</a>`:`<a href="tel:${esc(m.value)}">${esc(m.value)}</a>`}${m.companyName?`<small>${esc(m.companyName)}</small>`:''}</div>${copyButton(m.value)}</div>`).join('')}</div></section>`}
function historyDrawer(data){const rows=Array.isArray(data.jobHistory)?data.jobHistory:[];if(!rows.length)return'';return `<details class="data-drawer"><summary><span>Employment history</span><b>${rows.length}</b></summary><div class="drawer-content history-pills">${rows.map(r=>`<div class="history-pill"><strong>${esc(r.companyName||'Company')}</strong>${r.title?`<span>${esc(r.title)}</span>`:''}<small>No company-specific contact mapping supplied by Seamless.</small></div>`).join('')}</div></details>`}
function otherDrawer(methods){const arr=Array.isArray(methods)?methods:[];if(!arr.length)return'';return `<details class="data-drawer"><summary><span>Other returned contact data</span><b>${arr.length}</b></summary><div class="drawer-content">${methodRows('Company not confirmed by Seamless',arr)}</div></details>`}
function creditAuditLine(job,cached=false){if(cached)return'<span class="audit-chip ok">Cache · 0 new research requests</span>';const d=job.creditDelta;if(d===1)return'<span class="audit-chip ok">1 credit observed</span>';if(d===0)return'<span class="audit-chip ok">0-credit delta observed</span>';if(Number.isFinite(d)&&d>1)return`<span class="audit-chip danger">Credit anomaly · ${esc(d)} credits</span>`;return'<span class="audit-chip">Credit debit reconciling</span>'}
function companyChooser(data,record){const options=Array.isArray(data.companyContexts)?data.companyContexts:[];if(options.length<=1)return'';const selected=record?.companyContext||0;return `<div class="company-context"><div class="company-context-head"><span>MULTIPLE ROLES</span><small>Choose context · 0 credits</small></div><div class="company-options">${options.map((c,i)=>`<button type="button" data-company-context="${i}" class="company-option ${i===selected?'selected':''}"><span>${c.current?'CURRENT':'HISTORY'}</span><strong>${esc(c.companyName)}</strong></button>`).join('')}</div><div class="company-context-note">${selectedCompanyNote(data,selected)}</div></div>`}
function selectedCompanyNote(data,index=0){const options=Array.isArray(data.companyContexts)?data.companyContexts:[],selected=options[index]||options[0];if(!selected)return'';return selected.current?`Current Seamless record: ${esc(selected.companyName)}.`:`${esc(selected.companyName)} is historical. Returned emails/phones are not automatically attributed to that former role.`}
function newSlide(url){const feed=$('result-feed');const welcome=$('welcome-slide');if(welcome)welcome.remove();const slide=document.createElement('article');slide.className='result-slide';slide.id=`result-${++state.slideSeq}`;slide.dataset.url=url;slide.innerHTML='<div class="slide-card"><div class="loading-line"></div></div>';feed.append(slide);state.activeSlide=slide;state.records.set(slide.id,{job:null,companyContext:0,url});requestAnimationFrame(()=>slide.scrollIntoView({behavior:'smooth',block:'start'}));return slide}
function registerJob(slide,job){const rec=state.records.get(slide.id)||{companyContext:0,url:slide.dataset.url};rec.job=job;state.records.set(slide.id,rec);if(slide===state.activeSlide)state.currentJob=job;return rec}
function renderProcessing(job,slide=state.activeSlide){if(!slide)return;registerJob(slide,job);slide.innerHTML=`<div class="slide-card processing-card"><div class="processing-top"><div class="linkedin-badge large">in</div><div><span class="section-kicker">ENRICHING EXACT PROFILE</span><h2>Finding contact details…</h2><p>${esc(job.normalizedUrl||slide.dataset.url||'')}</p></div><span class="research-status"><i></i> Live</span></div><div class="progress-rail"><span></span></div><div class="processing-steps"><span class="done">✓ Profile submitted</span><span>↻ Polling one request</span><span>✦ Organizing result</span></div><div class="processing-foot">No search fan-out · no automatic duplicate submission · ${esc(job.keySource||job.routeId||'active organization')}</div></div>`}
function renderCompleted(job,cached=false,slide=state.activeSlide){
  if(!slide)return;const record=registerJob(slide,job);record.companyContext=record.companyContext||0;const d=job.data||{};const person=Array.isArray(d.personMethods)?d.personMethods:[];const current=Array.isArray(d.currentCompanyMethods)?d.currentCompanyMethods:[];const other=Array.isArray(d.unassignedMethods)?d.unassignedMethods:[];
  slide.innerHTML=`<div class="slide-card contact-card"><div class="contact-top"><div class="avatar">${esc(initials(d.fullName))}</div><div class="contact-title"><span>${cached?'CACHED CONTACT':'ENRICHED CONTACT'}</span><h2>${esc(d.fullName||'Contact')}</h2><p>${esc(d.company||'Company not returned')}</p></div><div class="contact-actions">${creditAuditLine(job,cached)}<span class="route-chip">${esc((job.routeId||'primary').toUpperCase())}</span></div></div>${companyChooser(d,record)}<div class="contact-grid"><div class="contact-column">${methodRows(`Current company · ${d.company||'Unknown'}`,current)||'<div class="empty-method">No current-company contact data returned.</div>'}</div><div class="contact-column">${methodRows('Personal / direct',person)||'<div class="empty-method">No personal/direct contact data returned.</div>'}</div></div><div class="drawer-row">${otherDrawer(other)}${historyDrawer(d)}${diagnosticDrawer(job)}</div><div class="slide-footer"><span>${esc(job.normalizedUrl||d.linkedinUrl||slide.dataset.url||'')}</span><span>Scroll ↑ for previous contact</span></div></div>`;
  const note=slide.querySelector('.company-context-note');if(note)note.innerHTML=selectedCompanyNote(d,record.companyContext);requestAnimationFrame(()=>slide.scrollIntoView({behavior:'smooth',block:'start'}));
}
function renderFailure(job,slide=state.activeSlide){if(!slide)return;registerJob(slide,job);slide.innerHTML=`<div class="slide-card failure-card"><div class="error-icon">!</div><div><span class="section-kicker">NO AMBIGUOUS RETRY</span><h2>Research needs attention</h2><p>${esc(job.message||`Research ended with status: ${job.status}.`)}</p>${diagnosticDrawer(job)}</div></div>`}
async function pollUntilDone(job,url,slide){if(job.status==='done'){renderCompleted(job,Boolean(job.cached),slide);return}if(!['submitting','processing'].includes(job.status)){renderFailure(job,slide);return}renderProcessing(job,slide);for(let i=0;i<40&&['submitting','processing'].includes(job.status);i++){await new Promise(r=>setTimeout(r,2500));job=await api('/v1/person/research/status',{linkedinUrl:url});if(['submitting','processing'].includes(job.status))renderProcessing(job,slide)}if(job.status==='done'){renderCompleted(job,false,slide);checkConnection().catch(()=>{});toast(job.creditDelta===1?'Contact enriched — 1 credit observed.':'Contact enriched and saved.')}else if(['submitting','processing'].includes(job.status)){renderProcessing(job,slide);toast('Still processing. No second research request was submitted.')}else renderFailure(job,slide)}
async function enrich(){
  if(state.busy)return;const input=$('linkedin');const url=validLinkedIn(input.value.trim());if(!url)return toast('Paste a LinkedIn person URL such as https://www.linkedin.com/in/name/.');state.busy=true;$('send').disabled=true;$('send').innerHTML='<span>Enriching</span><span class="spinner"></span>';const slide=newSlide(url);slide.innerHTML='<div class="slide-card checking-card"><div class="searching-orb"><span></span></div><div><span class="section-kicker">CACHE FIRST</span><h2>Checking this profile…</h2><p>If it is new, Beast submits exactly one direct LinkedIn research request.</p></div></div>';
  try{const lookup=await api('/v1/person/lookup',{linkedinUrl:url});state.lookup=lookup;if(lookup.cached&&lookup.job?.status==='done'){renderCompleted(lookup.job,true,slide);input.select();return}if(lookup.job&&['processing','submitting'].includes(lookup.job.status)){await pollUntilDone(lookup.job,url,slide);input.select();return}if(lookup.job&&!lookup.readyToResearch){renderFailure(lookup.job,slide);input.select();return}renderProcessing({status:'submitting',normalizedUrl:url},slide);const job=await api('/v1/person/research',{linkedinUrl:url});await pollUntilDone(job,url,slide);input.select()}catch(err){const failure={status:'failed',normalizedUrl:url,message:err.message,diagnosticTrace:err.payload?.diagnosticTrace||[]};registerJob(slide,failure);slide.innerHTML=`<div class="slide-card failure-card"><div class="error-icon">!</div><div><span class="section-kicker">REQUEST STOPPED</span><h2>Could not enrich this profile</h2><p>${esc(err.message)}</p>${diagnosticDrawer(failure)}</div></div>`;toast(err.message)}finally{state.busy=false;$('send').disabled=false;$('send').innerHTML='<span>Enrich</span><span>→</span>'}
}
$('chat-form').addEventListener('submit',e=>{e.preventDefault();enrich()});
$('result-feed').addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;const slide=b.closest('.result-slide');if(b.dataset.companyContext!==undefined&&slide){const rec=state.records.get(slide.id);if(!rec?.job?.data)return;rec.companyContext=Number(b.dataset.companyContext)||0;slide.querySelectorAll('.company-option').forEach(x=>x.classList.toggle('selected',x===b));const note=slide.querySelector('.company-context-note');if(note)note.innerHTML=selectedCompanyNote(rec.job.data,rec.companyContext);return}if(b.dataset.copyDiagnostic!==undefined&&slide){const rec=state.records.get(slide.id);if(!rec?.job)return;try{await navigator.clipboard.writeText(diagnosticReport(rec.job));toast('Diagnostic report copied')}catch{toast('Copy is unavailable in this browser.')}return}if(b.dataset.copy!==undefined){try{await navigator.clipboard.writeText(b.dataset.copy);toast('Copied to clipboard')}catch{toast('Copy is unavailable in this browser.')}}});
$('credits').onclick=async()=>{await checkConnection().catch(()=>{});$('credits-dialog').showModal()};$('credits-close').onclick=()=>$('credits-dialog').close();
function view(prospecting){$('enriching-view').hidden=prospecting;$('prospecting-view').hidden=!prospecting;$('enriching-nav').classList.toggle('active',!prospecting);$('prospecting-nav').classList.toggle('active',prospecting);$('page-label').textContent=prospecting?'Prospecting':'Enrichment Studio'}$('enriching-nav').onclick=()=>view(false);$('prospecting-nav').onclick=()=>view(true);$('back').onclick=()=>view(false);$('logout').onclick=()=>location.replace('/');
async function checkConnection(){try{const result=await api('/status');const providerOk=['READY','DEGRADED'].includes(result.seamless?.status);const ok=result.database?.status==='READY'&&providerOk;$('connection-label').textContent=ok?'Connected':'Needs attention';$('connect').classList.toggle('bad',!ok);if(result.credits)updateCredits(result.credits)}catch{$('connection-label').textContent='Offline';$('connect').classList.add('bad')}}$('connect').onclick=checkConnection;
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible')checkConnection().catch(()=>{})});
(async()=>{try{const r=await fetch('/health',{cache:'no-store'}),h=await r.json();$('build-label').textContent=`v${h.version}`;}catch{$('build-label').textContent='v40.1-test'}await checkConnection()})();
